<?php declare(strict_types=1);
$upcomingBase=$calendarBase+['date'=>$day->format('Y-m-d'),'upcoming_months'=>(string)($calendarUpcoming['offset']??0)];
?>
<aside class="calendar-list" data-calendar-upcoming>
<header class="calendar-upcoming-heading"><h2><?=e($calendarText('Termine und folgende Monate'))?></h2>
<?php if($calendarUpcoming!==null):?><p><?=e($calendarFormat('{from} bis {to}',['from'=>dateDe($calendarUpcoming['from']),'to'=>dateDe($calendarUpcoming['last'])]))?></p><p><?=e($calendarFormat('{count} Termine · Seite {page} von {pages}',['count'=>$calendarUpcoming['total'],'page'=>$calendarUpcoming['page'],'pages'=>$calendarUpcoming['pages']]))?></p><?php endif?></header>
<form class="search-form" method="get"><?=hidden('view','calendar').hidden('date',$day->format('Y-m-d')).hidden('mode',$calendarMode).hidden('calendar_filter',$calendarFilter).hidden('upcoming_months',(string)($calendarUpcoming['offset']??0))?><label class="sr-only" for="event-search"><?=e($calendarText('Termine in diesen Monaten suchen'))?></label><input class="form-control" id="event-search" name="q" maxlength="150" placeholder="<?=e($calendarText('Termine suchen'))?>" value="<?=e($term)?>"><button class="btn btn-outline theme-secondary icon-button" aria-label="<?=e($calendarText('Termine suchen'))?>"><?=icon('search')?></button></form>
<?php if($term!==''):?><p class="calendar-upcoming-reset"><a class="btn btn-outline theme-secondary" href="<?=e(url(array_replace($upcomingBase,['q'=>''])))?>"><?=e($calendarText('Suche zurücksetzen'))?></a></p><?php endif?>
<?php if($calendarUpcomingFailure!==''):?><p class="calendar-empty" role="alert"><?=e($calendarText($calendarUpcomingFailure))?></p><a class="btn btn-outline theme-secondary calendar-upcoming-reset" href="<?=e(url(array_replace($upcomingBase,['upcoming_page'=>'1'])))?>"><?=e($calendarText('Erste Seite der Terminliste'))?></a>
<?php elseif($calendarUpcoming!==null):?>
<div class="calendar-upcoming-entries" tabindex="0" role="region" aria-label="<?=e($calendarText('Terminliste für folgende Monate'))?>">
<?php foreach($calendarUpcoming['groups'] as $month=>$entries):?><section class="calendar-upcoming-month" data-calendar-upcoming-month="<?=e($month)?>"><h3><?=e($calendarText($months[(int)substr($month,5,2)-1]).' '.substr($month,0,4))?></h3>
<?php foreach($entries as $ev):$startDay=substr(localDateTime($ev['starts_at']),0,10);$endDay=substr(localDateTime($ev['ends_at']),0,10);$hasEnd=$ev['end_known']??true;$route=array_replace($upcomingBase,['upcoming_page'=>(string)$calendarUpcoming['page']],$ev['route']??['view'=>'calendar','event'=>$ev['id']]);?><a class="event-list-item" data-calendar-upcoming-event="<?=e($ev['id'])?>" href="<?=e(url($route))?>"><span class="event-date"><?=e(dateDe($startDay).($hasEnd&&$endDay!==$startDay?' – '.dateDe($endDay):''))?></span><span class="calendar-source <?=e(\Kulturhus\Verein\Events\Calendar\Presentation::css($ev))?>"><?=e($calendarText(\Kulturhus\Verein\Events\Calendar\Presentation::label($ev)))?></span><strong><?=e($ev['title'])?></strong><small><?=e((!empty($ev['all_day'])?$calendarText('Ganztägig'):timeDe($ev['starts_at']).($hasEnd?'–'.timeDe($ev['ends_at']):'')).($ev['location']!==''?' · '.$ev['location']:''))?></small></a><?php endforeach?></section><?php endforeach?>
<?php if($calendarUpcoming['total']===0):?><p class="calendar-empty"><?=e($calendarText($term!==''?'Für diese sechs Monate gibt es keine Treffer für deine Suche. Du kannst die folgenden Monate öffnen.':'Für diese sechs Monate gibt es keine Termine. Du kannst die folgenden Monate öffnen.'))?></p><?php endif?>
</div>
<nav class="calendar-upcoming-pages" aria-label="<?=e($calendarText('Seiten der Terminliste'))?>"><?php if($calendarUpcoming['page']>1):?><a class="btn btn-outline theme-secondary" data-upcoming-page="previous" href="<?=e(url($upcomingBase+['upcoming_page'=>(string)($calendarUpcoming['page']-1)]))?>"><?=e($calendarText('Vorige Termine'))?></a><?php endif?><?php if($calendarUpcoming['page']<$calendarUpcoming['pages']):?><a class="btn btn-outline theme-secondary" data-upcoming-page="next" href="<?=e(url($upcomingBase+['upcoming_page'=>(string)($calendarUpcoming['page']+1)]))?>"><?=e($calendarText('Weitere Termine'))?></a><?php endif?></nav>
<nav class="calendar-upcoming-pages" aria-label="<?=e($calendarText('Monate der Terminliste'))?>"><?php if($calendarUpcoming['offset']>0):?><a class="btn btn-outline theme-secondary" data-upcoming-months="previous" href="<?=e(url(array_replace($upcomingBase,['upcoming_months'=>(string)($calendarUpcoming['offset']-\Kulturhus\Verein\Web\CalendarUpcoming::MONTHS)])))?>"><?=e($calendarText('Vorige sechs Monate'))?></a><?php endif?><?php if($calendarUpcoming['offset']<\Kulturhus\Verein\Web\CalendarUpcoming::MAX_MONTH_OFFSET):?><a class="btn btn-outline theme-secondary" data-upcoming-months="next" href="<?=e(url(array_replace($upcomingBase,['upcoming_months'=>(string)($calendarUpcoming['offset']+\Kulturhus\Verein\Web\CalendarUpcoming::MONTHS)])))?>"><?=e($calendarText('Folgende sechs Monate'))?></a><?php endif?></nav>
<?php endif?>
</aside>
